const ultimoPeriodoCerrado = `-- name: UltimoPeriodoCerrado :one
SELECT max(periodo)::date AS periodo FROM liquidaciones
 WHERE consorcio_id = $1 AND estado IN ('aprobada', 'emitida')
`

// Último período aprobado o emitido (null si no hay): las tasas y parámetros nuevos tienen
// que regir después, para no cambiar una liquidación cerrada.
func (q *Queries) UltimoPeriodoCerrado(ctx context.Context, consorcioID uuid.UUID) (fecha.Fecha, error) {
	row := q.db.QueryRow(ctx, ultimoPeriodoCerrado, consorcioID)
	var periodo fecha.Fecha
	err := row.Scan(&periodo)
	return periodo, err
}
